import json
import os
import tempfile
from functools import lru_cache
from typing import Dict, Iterable, Optional

from googleapiclient.discovery import build
from googleapiclient.errors import HttpError
from googleapiclient.http import MediaFileUpload
from google.oauth2 import service_account

import logging

logger = logging.getLogger(__name__)

SCOPES = ["https://www.googleapis.com/auth/drive"]


class GoogleDriveService:
    """Thin wrapper around Google Drive API for service-account uploads."""

    def __init__(self, credentials_info: Dict[str, str], impersonate_user: Optional[str] = None):
        credentials = service_account.Credentials.from_service_account_info(credentials_info, scopes=SCOPES)
        if impersonate_user:
            credentials = credentials.with_subject(impersonate_user)
        self._service = build("drive", "v3", credentials=credentials, cache_discovery=False)

    def ensure_folder(self, name: str, parent_id: Optional[str] = None) -> str:
        """Fetch an existing folder by name (within parent) or create it."""
        query_parts = ["mimeType='application/vnd.google-apps.folder'", f"name='{name.replace("'", "\\'")}'", "trashed=false"]
        if parent_id:
            query_parts.append(f"'{parent_id}' in parents")
        query = " and ".join(query_parts)
        response = self._service.files().list(q=query, spaces="drive", fields="files(id, name)").execute()
        files = response.get("files", [])
        if files:
            folder_id = files[0]["id"]
            logger.debug("Reusing Drive folder %s (%s)", name, folder_id)
            return folder_id

        file_metadata = {
            "name": name,
            "mimeType": "application/vnd.google-apps.folder",
        }
        if parent_id:
            file_metadata["parents"] = [parent_id]
        folder = self._service.files().create(body=file_metadata, fields="id").execute()
        folder_id = folder["id"]
        logger.info("Created Drive folder %s (%s)", name, folder_id)
        return folder_id

    def upload_file(self, *, file_path: str, drive_name: str, drive_folder_id: str, mimetype: Optional[str] = None) -> str:
        media = MediaFileUpload(file_path, mimetype=mimetype, resumable=True)
        body = {"name": drive_name, "parents": [drive_folder_id]}
        file = self._service.files().create(body=body, media_body=media, fields="id").execute()
        file_id = file["id"]
        logger.info("Uploaded %s to Drive folder %s (file_id=%s)", drive_name, drive_folder_id, file_id)
        return file_id


def _load_credentials_from_env() -> Optional[Dict[str, str]]:
    raw_path = os.getenv("GOOGLE_DRIVE_SERVICE_ACCOUNT_FILE")
    raw_json = os.getenv("GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON")
    raw_base64 = os.getenv("GOOGLE_DRIVE_SERVICE_ACCOUNT_B64")

    if raw_json:
        return json.loads(raw_json)
    if raw_base64:
        import base64

        decoded = base64.b64decode(raw_base64)
        return json.loads(decoded)
    if raw_path:
        with open(raw_path, "r", encoding="utf-8") as fp:
            return json.load(fp)
    return None


@lru_cache(maxsize=1)
def get_drive_service() -> Optional[GoogleDriveService]:
    credentials_info = _load_credentials_from_env()
    if not credentials_info:
        logger.warning("Google Drive credentials not configured; skipping Drive integration")
        return None
    impersonate_user = os.getenv("GOOGLE_DRIVE_IMPERSONATE")
    try:
        return GoogleDriveService(credentials_info, impersonate_user=impersonate_user)
    except HttpError as exc:
        logger.error("Failed to initialize Google Drive service: %s", exc)
        return None
    except Exception as exc:  # pragma: no cover - defensive
        logger.exception("Unexpected error initializing Google Drive service")
        return None


def write_temp_file(name: str, data: str) -> str:
    fd, path = tempfile.mkstemp(prefix="drive-export-", suffix=f"-{name}")
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(data)
    return path
